"""Generate promptfooconfig.yaml from cases.yaml (single source of truth).

python security/promptfoo/build_config.py          # rewrite the config
python security/promptfoo/build_config.py --check  # exit 1 if out of date
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

import yaml

HERE = Path(__file__).resolve().parent
CONFIG = HERE / "promptfooconfig.yaml"
HEADER = (
    "# GENERATED by security/promptfoo/build_config.py from cases.yaml -- do not edit.\n"
    "# Offline: the provider runs the direct executor's tool guards in a sandbox; no model, no network.\n"
)


def render() -> str:
    cases = yaml.safe_load((HERE / "cases.yaml").read_text(encoding="utf-8"))
    config = {
        "description": "OC direct-executor tool-guard red team (offline)",
        "prompts": ["{{payload}}"],
        "providers": [
            {"id": "file://provider.py", "label": "oc-direct-executor-guards"}
        ],
        "tests": [
            {
                "description": f"{case['id']}: {case['description']}",
                "vars": {
                    "payload": json.dumps(
                        {"tool": case["tool"], "input": case["input"]}, sort_keys=True
                    )
                },
                "assert": [{"type": "starts-with", "value": f"{case['expect']}:"}]
                + [
                    {"type": "not-contains", "value": token}
                    for token in (case.get("argv_must_not_contain") or [])
                    + (case.get("output_must_not_contain") or [])
                ],
            }
            for case in cases
        ],
    }
    return HEADER + yaml.safe_dump(config, sort_keys=False, width=1000)


def main() -> int:
    rendered = render()
    if "--check" in sys.argv:
        current = CONFIG.read_text(encoding="utf-8") if CONFIG.exists() else ""
        if current != rendered:
            print("promptfooconfig.yaml is out of date; run build_config.py")
            return 1
        return 0
    CONFIG.write_text(rendered, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
